def intent(text=None, append=False):
    p = "intent.md"
    if text is None:
        try:
            return open(p).read()
        except FileNotFoundError:
            return ""
    mode = "a" if append else "w"
    with open(p, mode) as f:
        f.write(text if text.endswith("\n") else text + "\n")
    return open(p).read()

